#include <iostream>
#include <string>
using namespace std;

string parseHeading(const string& line) {
    int level = 0;
    while (level < (int)line.size() && line[level] == '#') level++;
    if (level > 0 && level <= 3) {
        string content = line.substr(level);
        while (!content.empty() && content[0] == ' ') content = content.substr(1);
        return "<h" + to_string(level) + ">" + content + "</h" + to_string(level) + ">";
    }
    return line;
}

int main() {
    cout << parseHeading("# Title") << endl;
    cout << parseHeading("## Section") << endl;
    cout << parseHeading("### Subsection") << endl;
    return 0;
}
